function liveLegalLinks(){return '<a href="legal/privacy.html">隐私政策</a> · <a href="legal/terms.html">用户协议</a> · <a href="legal/rules.html">社区规则</a> · <a href="legal/age-18.html">十八岁以上声明</a> · <a href="legal/retention.html">保留期限</a> · <a href="#/govern">第三方投诉</a>';}
let sessionReturnTo='', previousSessionState=window.CommonsSession?.state||'loading';
const publicRoutes=new Set(['hello','welcome','login','govern']);
const sessionMember=()=>window.CommonsSession?.state==='member';
function sessionRetry(){window.CommonsSession?.refresh().catch(()=>{});}
function sessionNotice(){return window.CommonsSession?.error?'<div class="page" role="alert"><p>账号信息没有加载出来。</p><button class="button" data-action="session-retry">重试</button></div>':'';}
const liveAvatarUrls={};
function loadLiveAvatar(ref){if(ref in liveAvatarUrls||!window.CommonsAPI?.get)return;liveAvatarUrls[ref]='';window.CommonsAPI.get('/media/assets/'+encodeURIComponent(ref)).then(r=>{const sizes=r?.data?.sizes||{};const url=sizes['64']||sizes['128']||sizes['256']||'';const safe=url?safeUrl(url):'';if(safe&&safe!=='#'){liveAvatarUrls[ref]=safe;window.Commons.refresh?.();}else delete liveAvatarUrls[ref];}).catch(()=>{delete liveAvatarUrls[ref];});}
let liveAvatarOverride=null;
function liveAvatar(me){const initial=Array.from(String(me.display_name||me.handle||''))[0]||'';const ref=liveAvatarOverride?liveAvatarOverride.ref:typeof me.avatar_ref==='string'?me.avatar_ref.trim():'';let src='';if(liveAvatarOverride){src=liveAvatarOverride.url?safeUrl(liveAvatarOverride.url):'';}else if(ref){if(/^(?:\/(?!\/)|assets\/|https?:\/\/)/i.test(ref))src=safeUrl(ref);else{src=liveAvatarUrls[ref]||'';if(!(ref in liveAvatarUrls))loadLiveAvatar(ref);}}return src&&src!=='#'?`<img class="member-self-avatar" src="${safeUrl(src)}" alt="" width="32" height="32">`:`<span class="member-self-avatar member-color-blue" aria-hidden="true">${esc(initial)}</span>`;}
function onLiveAvatar(event){const d=event.detail||{};const me=window.CommonsSession?.me;if(!me)return;liveAvatarOverride={ref:typeof d.avatar_ref==='string'?d.avatar_ref:'',url:typeof d.url==='string'?d.url:''};document.querySelectorAll('.top-member .member-self-avatar, .sh-me .member-self-avatar').forEach(node=>{node.outerHTML=/* safe-fn: liveAvatar 内逐值转义，src 过 safeUrl */ liveAvatar(me);});}
function liveMemberLink(){const me=window.CommonsSession.me;return `<a class="top-member" href="#/account" aria-label="账号与隐私">${liveAvatar(me)}<span>${esc(me.display_name||me.handle)} <small>L${esc(Number(me.level)||1)}</small></span></a>`;}
function liveTopActions(){return `<button class="search-trigger" data-action="search" aria-label="搜索">${icon('search')}<span>搜索</span><kbd>⌘ K</kbd></button>${/* safe: 余额、私信和通知模块各自转义 */ window.CommonsEconomy?.badge?.()||''}${/* safe: 私信模块自行转义 */ window.CommonsDM?.badge?.()||''}${/* safe: 通知模块自行转义 */ window.CommonsNotify?.bell()||''}${liveMemberLink()}`;}
