 $('#sidebar').innerHTML='';$('#mobile-nav')._dmObserver?.disconnect();$('#mobile-nav').innerHTML='';$('#announce-slot').innerHTML='';
 $('#topbar').innerHTML=`<a class="wordmark" href="#/hello">${brandMark()}<span>先锋</span></a>`;
