function showcaseCard(w){return `<article class="work-line"><a class="work-line-art" href="#/work/${esc(w.id)}" aria-label="查看${esc(w.title)}"><span class="work-preview-content" aria-hidden="true">${window.CommonsShowcase.preview(w)}</span></a><div class="work-line-copy"><div class="work-line-heading"><a href="#/work/${esc(w.id)}"><h3>${esc(w.title)}</h3></a><span class="work-line-kind">${esc(w.kind)}</span></div><p>${esc(w.subtitle)}</p><div class="work-line-footer"><div class="work-line-person"><a href="#/people/${esc(w.owner)}">${avatar(w.owner,'tiny')} ${esc(person(w.owner).name)}</a><span>${w.evidence.length} 类证据</span></div><div class="work-line-actions"><a href="#/work/${esc(w.id)}" class="button ghost">打开作品 ${icon('arrow')}</a><button class="button" data-action="connect-buddy" data-id="${esc(w.owner)}" aria-label="${esc(w.owner===window.Commons.currentPersonId?'发起组队':'约'+person(w.owner).name+'共作')}"><span class="work-action-full">${w.owner===window.Commons.currentPersonId?'发起组队':'约作者共作'}</span><span class="work-action-short">${w.owner===window.Commons.currentPersonId?'组队':'共作'}</span>${icon('arrow')}</button></div></div></div></article>`;}
function home(){if(LIVE)return window.CommonsShowcase?.home?window.CommonsShowcase.home():liveEmpty('today');
 const goal=read('goal',D.goals[0]),list=goal===D.goals[1]?[D.methods[4],D.methods[1]]:goal===D.goals[2]?[D.methods[5],D.methods[2]]:[D.methods[0],D.methods[1]];
 const practiceId=D.methods.some(m=>m.id===read('last-practice','k1'))?read('last-practice','k1'):'k1';
 const completed=read('practice.'+practiceId,{}),done=[Boolean(completed.title&&completed.goal),completed.checks?.length===3,Boolean(completed.result),Boolean(completed.reflection)].filter(Boolean).length;
 const selectedWork=state.spotlight||['w1','w2','w3'][Math.max(0,D.goals.indexOf(goal))];
 return window.CommonsShowcase.home({goal,list,done,practiceId,selectedWork,selectedStep:state.spotlightStep,stage:state.homeStage});
}
