document.addEventListener('click',event=>{const scrollEl=event.target.closest('[data-scroll]');if(scrollEl){event.preventDefault();const target=document.getElementById(scrollEl.dataset.scroll);if(target?.hasAttribute('tabindex'))target.focus({preventScroll:true});target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}const button=event.target.closest('[data-action]');if(button){event.preventDefault();button.focus({preventScroll:true});try{handle(button.dataset.action,button);}catch(error){console.error('Prototype action failed',error);toast('刚才的操作没有完成。输入还在，请重试或返回上一页。');}return;}const anchor=event.target.closest('a[href^="#/"]');if(anchor){closeModal(true);setMenu(false,false);}else if(!event.target.closest('#sidebar')&&!event.target.closest('[data-action="menu"]'))setMenu(false);});
